DATA = json.loads(zlib.decompress(base64.b85decode(FIXTURE)))


def reports():
    # SARIF was produced by the retained, hash-verified native Trivy 0.70.0
    # converter, independently of the implementation under test.
    return tuple(copy.deepcopy(DATA[k]) for k in ('synthetic_fs', 'actual_config', 'synthetic_sarif'))


def findings(report):
    return [(r, f) for r in report['Results'] for f in r.get('Misconfigurations', [])]


def env_fixture(root, temp):
    event = temp / 'event.json'
    event.write_text(c.canonical(dict(repository=dict(full_name=c.REPOSITORY),
        pull_request=dict(base=dict(repo=dict(full_name=c.REPOSITORY)), head=dict(sha='a'*40)))))
    return dict(PATH=os.environ['PATH'], HOME=str(temp), GITHUB_WORKSPACE=str(root), RUNNER_TEMP=str(temp),
        GITHUB_EVENT_PATH=str(event), GITHUB_OUTPUT=str(temp/'output'), GITHUB_EVENT_NAME='pull_request',
        GITHUB_REPOSITORY=c.REPOSITORY, CC_REPOSITORY=c.REPOSITORY, CC_HEAD_SHA='a'*40,
        CC_WORKFLOW_REF=c.WORKFLOW_REF, CC_WORKFLOW_SHA='b'*40,
        GITHUB_WORKFLOW_REF=c.WORKFLOW_REF, GITHUB_WORKFLOW_SHA='b'*40, GITHUB_RUN_ID='123', GITHUB_RUN_ATTEMPT='1')


def rejected_repository_urls():
    origin = 'https://github.com/' + c.REPOSITORY
    variants = [
        'https://github.com/foreign/repo', origin + '-foreign', origin + '.git.git',
        origin + '/', origin + '.git/', origin + '/extra', origin + '?x=1',
        origin + '.git?x=1', origin + '#main', origin + '.git#main',
        origin.replace('https:', 'http:'), origin.replace('https:', 'git:'),
        origin.replace('https:', 'ssh:'), 'git@github.com:' + c.REPOSITORY + '.git',
        origin.replace('github.com', 'github.com.evil.invalid'),
        origin.replace('github.com', 'github.com:443'),
        origin.replace('github.com', 'user@github.com'),
        origin.replace('github.com', 'user:password@github.com'),
        origin.replace('github.com', 'github.com@evil.invalid'),
        origin.replace('github.com', 'GITHUB.COM'), origin.lower(),
        origin.replace('/CyberCoach-NC', '/other/../CyberCoach-NC'),
        origin.replace('/CyberCoach-NC', '//CyberCoach-NC'),
        origin.replace('CyberCoach', '%43yberCoach'), origin + '%2Egit',
        origin.replace('https://', 'https:\\'), '',
    ]
    for suffix in ('', '.git'):
        for space in (' ', '\t', '\r', '\n', '\v', '\f', '\u00a0'):
            variants.extend((space + origin + suffix, origin + suffix + space))
    return variants


class Contract(unittest.TestCase):
    def test_real_config_and_full_category_fixture(self):
        fs, config, sarif = reports()
        original = c.canonical([fs, config, sarif])
        receipt = c.classify(fs, config, sarif)
        self.assertEqual(c.canonical([fs, config, sarif]), original)
        self.assertEqual(len(receipt['accepted_high_findings']), 2)
        self.assertEqual(len(receipt['iac_findings']), 7)
        self.assertEqual(receipt['finding_counts_by_kind_and_severity']['Licenses/UNKNOWN'], 3)
        self.assertEqual(receipt['unaccepted_high_critical_findings'], [])

    def test_current_fixture_records_actual_scan_coverage(self):
        # Current full scan uses the same four production scanners and one pinned DB.
        self.assertEqual(DATA['actual_scan_coverage']['scanners'], ['vuln', 'misconfig', 'secret', 'license'])
        self.assertTrue(DATA['actual_scan_coverage']['vulnerability_scan_performed'])
        argv = c.commands('/trusted/trivy', Path('/source'), Path('/out'), Path('/cache'))[0]
        self.assertEqual(argv[argv.index('--scanners') + 1], 'vuln,misconfig,secret,license')
        self.assertNotIn('--skip-db-update', argv)

    def test_previous_frontdoor_and_cloudtrail_coordinates_rejected(self):
        for target in ('modules/public-frontdoor/main.tf', 'operator-database/stores.tf'):
            fs, config, sarif = (copy.deepcopy(DATA[k]) for k in ('actual_fs', 'actual_config', 'actual_sarif'))
            for report in (fs, config):
                for result, finding in findings(report):
                    if result['Target'].removeprefix('infra/aws/') == target:
                        cause = finding['CauseMetadata']
                        if target.startswith('modules/'):
                            cause['Occurrences'][0]['Location']['EndLine'] = 106
                        else:
                            cause['StartLine'] = cause['EndLine'] = 146
                            cause['Occurrences'][0]['Location'] = {'StartLine': 140, 'EndLine': 158}
            with self.subTest(target=target), self.assertRaisesRegex(ValueError, 'exact-iac-inventory'):
                c.classify(fs, config, sarif)

    def test_actual_current_scan_and_sarif_unfiltered_counts(self):
        result=c.classify(DATA['actual_fs'],DATA['actual_config'],DATA['actual_sarif'])
        self.assertEqual(sum(result['finding_counts_by_kind_and_severity'].values()),280)
        self.assertEqual(len(result['accepted_high_findings']),2)

    def test_both_exact_report_repository_urls_and_hostile_variants(self):
        for suffix in ('', '.git'):
            fs, config, sarif = reports()
            fs['Metadata']['RepoURL'] = 'https://github.com/' + c.REPOSITORY + suffix
            with self.subTest(suffix=suffix):
                self.assertEqual(len(c.classify(fs, config, sarif)['iac_findings']), 7)
        for value in rejected_repository_urls():
            fs, config, sarif = reports(); fs['Metadata']['RepoURL'] = value
            with self.subTest(url=value), self.assertRaisesRegex(ValueError, '^report-repository$'):
                c.classify(fs, config, sarif)

    def test_current_seven_observations_preserve_only_original_two_high_exceptions(self):
        values = tuple(copy.deepcopy(DATA[k]) for k in ('actual_fs', 'actual_config', 'actual_sarif'))
        before = c.canonical(values); receipt = c.classify(*values)
        self.assertEqual(c.canonical(values), before)
        self.assertEqual(len(receipt['iac_findings']), 7)
        self.assertEqual({(x['rule'], x['severity']) for x in receipt['iac_findings']}, {
            ('AWS-0132', 'HIGH'), ('AWS-0089', 'LOW'), ('AWS-0010', 'MEDIUM'),
            ('AWS-0066', 'LOW'), ('AWS-0014', 'MEDIUM')})
        self.assertEqual({(x['rule'], x['severity'], x['target'], x['resource'])
                          for x in receipt['accepted_high_findings']}, {
            ('AWS-0132', 'HIGH', 'operator-foundations/access-logging.tf',
             'aws_s3_bucket_server_side_encryption_configuration.access_logs'),
            ('AWS-0132', 'HIGH', 'modules/audit-foundation/receivers.tf', 'module.audit')})
        self.assertEqual(receipt['finding_counts_by_kind_and_severity']['Misconfigurations/LOW'], 3)
        self.assertEqual(receipt['finding_counts_by_kind_and_severity']['Misconfigurations/MEDIUM'], 2)
        for rule in ('AWS-0066', 'AWS-0014'):
            for severity in ('HIGH', 'CRITICAL'):
                fs, config, sarif = copy.deepcopy(values)
                for report in (fs, config):
                    for _, finding in findings(report):
                        if finding['ID'] == rule: finding['Severity'] = severity
                with self.subTest(rule=rule, severity=severity), self.assertRaises(ValueError):
                    c.classify(fs, config, sarif)

    def test_each_finding_missing_duplicate_or_field_changed(self):
        for which in (0, 1):
            for index in range(7):
                for change in ('missing','duplicate','rule','severity','target','provider','service','resource',
                               'start','end','occurrence','status','type','namespace','query'):
                    values = reports(); r, f = findings(values[which])[index]
                    if change == 'missing': r['Misconfigurations'].remove(f); r['MisconfSummary']['Failures'] -= 1
                    elif change == 'duplicate': r['Misconfigurations'].append(copy.deepcopy(f)); r['MisconfSummary']['Failures'] += 1
                    elif change == 'rule': f['ID'] = 'AWS-9999'
                    elif change == 'severity': f['Severity'] = 'LOW' if f['Severity'] != 'LOW' else 'HIGH'
                    elif change == 'target': r['Target'] = 'infra/aws/lookalike.tf' if which == 0 else 'lookalike.tf'
                    elif change in ('provider','service','resource'): f['CauseMetadata'][change.title()] = 'foreign'
                    elif change in ('start','end'): f['CauseMetadata'][change.title()+'Line'] += 1
                    elif change == 'occurrence': f['CauseMetadata']['Occurrences'] = [dict(Resource='foreign',Filename='new.tf',Location=dict(StartLine=1,EndLine=2))]
                    elif change == 'status': f['Status'] = 'PASS'
                    elif change == 'type': f['Type'] = 'Dockerfile Security Check'
                    elif change == 'namespace': f['Namespace'] = 'custom'
                    elif change == 'query': f['Query'] = 'custom.deny'
                    with self.subTest(report=which,index=index,change=change), self.assertRaises(ValueError):
                        c.classify(*values)

    def test_extra_iac_lookalike_and_new_native_or_caller(self):
        for target in ('infra/aws/new.tf','infra/aws/modules/new/main.tf','Dockerfile'):
            values = reports(); r, _ = findings(values[0])[0]; r = copy.deepcopy(r); r['Target'] = target
            values[0]['Results'].append(r)
            with self.subTest(target=target), self.assertRaises(ValueError): c.classify(*values)

    def test_all_other_high_critical_categories_fail(self):
        for kind in ('Vulnerabilities','Secrets','Licenses'):
            for severity in ('HIGH','CRITICAL'):
                values = reports()
                values[0]['Results'].append(dict(Target='hostile-'+kind,Class='lang-pkgs',Type='npm',**{kind:[dict(Severity=severity)]}))
                with self.subTest(kind=kind,severity=severity), self.assertRaisesRegex(ValueError,'unaccepted-high-critical'):
                    c.classify(*values)

    def test_new_low_medium_findings_remain_visible_not_fixed_count(self):
        values = reports()
        finding = copy.deepcopy(values[0]['Results'][-1]['Vulnerabilities'][0])
        finding['Severity'] = 'MEDIUM'
        values[0]['Results'][-1]['Vulnerabilities'] += [finding] * 300
        result = copy.deepcopy(next(r for r in values[2]['runs'][0]['results'] if r['ruleId'] == 'SYNTHETIC-LOW'))
        result['level'] = 'warning'
        result['message']['text'] = result['message']['text'].replace('Severity: LOW', 'Severity: MEDIUM')
        values[2]['runs'][0]['results'] += [result] * 300
        rule = next(r for r in values[2]['runs'][0]['tool']['driver']['rules'] if r['id'] == 'SYNTHETIC-LOW')
        rule['defaultConfiguration']['level'] = 'warning'
        rule['properties'].update(tags=['vulnerability', 'security', 'MEDIUM'], **{'security-severity': '5.5'})
        result = c.classify(*values)
        self.assertEqual(result['finding_counts_by_kind_and_severity']['Vulnerabilities/MEDIUM'],300)

    def test_unknown_missing_and_lowercase_severity_rejected(self):
        for value in (None,'low','SEVERE',True):
            values = reports(); values[0]['Results'][-1]['Vulnerabilities'][0]['Severity'] = value
            with self.subTest(value=value), self.assertRaises(ValueError): c.classify(*values)

    def test_report_schema_empty_duplicate_and_suppressed_fail(self):
        for which in (0,1):
            for mode in ('schema','version','artifact','empty','unknown-root','unknown-kind','duplicate-result','summary','zero-successes','exceptions'):
                values=reports(); d=values[which]
                if mode=='schema':d['SchemaVersion']=3
                elif mode=='version':d['Trivy']['Version']='0.71.0'
                elif mode=='artifact':d['ArtifactType']='container_image'
                elif mode=='empty':d['Results']=[]
                elif mode=='unknown-root':d['NewFindings']=[dict(Severity='HIGH')]
                elif mode=='unknown-kind':d['Results'][0]['NewFindings']=[dict(Severity='HIGH')]
                elif mode=='duplicate-result':d['Results'].append(copy.deepcopy(d['Results'][0]))
                elif mode=='summary':next(r for r in d['Results'] if 'MisconfSummary' in r)['MisconfSummary']['Failures']=999
                elif mode=='zero-successes':
                    for r in d['Results']:
                        if 'MisconfSummary' in r:r['MisconfSummary']['Successes']=0
                elif mode=='exceptions':next(r for r in d['Results'] if 'MisconfSummary' in r)['MisconfSummary']['Exceptions']=1
                with self.subTest(which=which,mode=mode), self.assertRaises(ValueError):c.classify(*values)

    def test_path_normalization_never_collapses_extra_prefix_or_traversal(self):
        for name in ('infra/aws/infra/aws/operator-foundations/access-logging.tf',
                     '/infra/aws/operator-foundations/access-logging.tf',
                     'infra/aws/../operator-foundations/access-logging.tf',
                     'infra/aws//operator-foundations/access-logging.tf',
                     'infra\\aws\\operator-foundations/access-logging.tf'):
            values=reports();findings(values[0])[0][0]['Target']=name
            with self.subTest(name=name),self.assertRaises(ValueError):c.classify(*values)

    def test_occurrence_schema_and_line_types(self):
        for mode in ('missing','extra','bool','prefix'):
            values=reports();f=next(f for _,f in findings(values[0]) if f['CauseMetadata'].get('Occurrences'))
            o=f['CauseMetadata']['Occurrences'][0]
            if mode=='missing':o.pop('Location')
            elif mode=='extra':o['unknown']=True
            elif mode=='bool':o['Location']['StartLine']=True
            elif mode=='prefix':o['Filename']='infra/aws/'+o['Filename']
            with self.subTest(mode=mode),self.assertRaises((ValueError,KeyError)):c.classify(*values)

    def test_sarif_missing_schema_and_results(self):
        for value in ({},dict(version='2.1.0',runs=[]),dict(version='2.1.0',runs=[dict(tool=dict(driver=dict(name='other')),results=[])])):
            fs,config,_=reports()
            with self.subTest(value=value),self.assertRaises((ValueError,KeyError)):c.classify(fs,config,value)

    def test_json_duplicate_nonfinite_malformed(self):
        for raw in ('{"a":1,"a":2}','{"a":NaN}','{',''):
            with self.subTest(raw=raw),self.assertRaises(ValueError):c.decode(raw)

