class SarifCorrespondence(unittest.TestCase):
    def actual(self):
        return tuple(copy.deepcopy(DATA[k]) for k in ('actual_fs', 'actual_config', 'actual_sarif'))

    def test_real_duplicates_and_full_extended_native_conversion(self):
        fs, config, sarif = self.actual()
        results = sarif['runs'][0]['results']
        self.assertLess(len({c.canonical(r) for r in results}), len(results))
        result = c.classify(fs, config, sarif)
        self.assertEqual(result['finding_counts_by_kind_and_severity']['Licenses/LOW'], 271)
        self.assertEqual(result['finding_counts_by_kind_and_severity']['Licenses/UNKNOWN'], 2)
        extended = c.classify(DATA['extended_fs'], config, DATA['extended_sarif'])
        self.assertEqual(extended['finding_counts_by_kind_and_severity']['Secrets/LOW'], 1)
        self.assertEqual(extended['finding_counts_by_kind_and_severity']['Vulnerabilities/MEDIUM'], 1)

    def test_reviewer_null_duplicate_substitution_and_failed_invocation(self):
        for mutation in ('null', 'duplicate', 'invocation'):
            fs, config, sarif = self.actual(); run = sarif['runs'][0]
            if mutation == 'null': run['results'] = [None] * len(run['results'])
            elif mutation == 'duplicate': run['results'] = [copy.deepcopy(run['results'][-1])] * len(run['results'])
            else: run['invocations'] = [dict(executionSuccessful=False, toolExecutionNotifications=[dict(level='error', message=dict(text='incomplete'))])]
            with self.subTest(mutation=mutation), self.assertRaises(ValueError): c.classify(fs, config, sarif)

    def test_each_exact_iac_result_cannot_be_replaced_at_same_count(self):
        original = self.actual()
        indexes = [i for i, r in enumerate(original[2]['runs'][0]['results']) if r['ruleId'].startswith('AWS-')]
        self.assertEqual(len(indexes), 7)
        for index in indexes:
            fs, config, sarif = self.actual(); results = sarif['runs'][0]['results']
            results[index] = copy.deepcopy(results[-1])
            with self.subTest(index=index), self.assertRaises(ValueError): c.classify(fs, config, sarif)

    def test_result_identity_location_severity_and_schema_mutations(self):
        for mutation in ('rule', 'index', 'bool-index', 'severity', 'message', 'message-null',
                         'uri', 'base', 'start', 'end', 'bool-line', 'column', 'locations-empty',
                         'location-null', 'extra-location', 'suppression', 'result-array'):
            fs, config, sarif = self.actual(); r = sarif['runs'][0]['results'][0]
            physical = r['locations'][0]['physicalLocation']
            if mutation == 'rule': r['ruleId'] = 'AWS-0010'
            elif mutation == 'index': r['ruleIndex'] = 999999
            elif mutation == 'bool-index': r['ruleIndex'] = False
            elif mutation == 'severity': r['level'] = 'error'
            elif mutation == 'message': r['message']['text'] += ' substituted'
            elif mutation == 'message-null': r['message'] = None
            elif mutation == 'uri': physical['artifactLocation']['uri'] = 'elsewhere.tf'
            elif mutation == 'base': physical['artifactLocation']['uriBaseId'] = 'OTHER'
            elif mutation == 'start': physical['region']['startLine'] += 1
            elif mutation == 'end': physical['region']['endLine'] += 1
            elif mutation == 'bool-line': physical['region']['startLine'] = True
            elif mutation == 'column': physical['region']['endColumn'] = 2
            elif mutation == 'locations-empty': r['locations'] = []
            elif mutation == 'location-null': r['locations'] = [None]
            elif mutation == 'extra-location': r['locations'].append(copy.deepcopy(r['locations'][0]))
            elif mutation == 'suppression': r['suppressions'] = [dict(kind='external')]
            else: sarif['runs'][0]['results'][0] = []
            with self.subTest(mutation=mutation), self.assertRaises(ValueError): c.classify(fs, config, sarif)

    def test_package_versions_and_duplicate_locations_preserve_multiplicity(self):
        for mutation in ('replace-version', 'drop-location', 'duplicate-location', 'drop-result'):
            fs = copy.deepcopy(DATA['extended_fs']); sarif = copy.deepcopy(DATA['extended_sarif'])
            results = sarif['runs'][0]['results']; matches = [r for r in results if r['ruleId'] == 'SYNTHETIC-LOW']
            self.assertEqual(len(matches), 2)
            r = next(r for r in matches if len(r['locations']) == 3)
            if mutation == 'replace-version': r['message'] = copy.deepcopy(matches[1]['message'])
            elif mutation == 'drop-location': r['locations'].pop()
            elif mutation == 'duplicate-location': r['locations'].append(copy.deepcopy(r['locations'][0]))
            else: results.remove(r)
            with self.subTest(mutation=mutation), self.assertRaises(ValueError): c.classify(fs, DATA['actual_config'], sarif)

    def test_result_and_location_order_are_not_identity(self):
        fs = copy.deepcopy(DATA['extended_fs']); sarif = copy.deepcopy(DATA['extended_sarif'])
        sarif['runs'][0]['results'].reverse()
        for r in sarif['runs'][0]['results']: r['locations'].reverse()
        c.classify(fs, DATA['actual_config'], sarif)

