        for severity in ('', None):
            fs, config, sarif = reports()
            fs['Results'][-1]['Licenses'][0]['Severity'] = severity
            license_result = next(r for r in sarif['runs'][0]['results'] if r['ruleId'] == 'synthetic:MIT')
            license_result['level'] = 'none'
